import gzip,glob,pandas as pd
pd.set_option('display.width',300,'display.max_rows',500,'display.max_colwidth',90)
def meta(f):
    rows={}
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'):break
        if l.startswith('!Sample_'):
            p=l.rstrip('\n').split('\t'); k=p[0]
            while k in rows: k+='_'
            rows[k]=[x.strip('"') for x in p[1:]]
    return pd.DataFrame(rows)
for f in sorted(glob.glob('studies/data/raw/*series_matrix*'))[1:]:
    d=meta(f)
    cols=[c for c in d.columns if any(k in c for k in ['geo_accession','title','characteristics','source_name'])]
    d=d[cols]
    # drop constant cols
    d=d[[c for c in d.columns if d[c].nunique()>1]]
    print(f); print(d.to_string())

